// main()

const crypto = require('crypto');

// 公钥 DER (SPKI) hex，从 ch27.js col 324576 提取（真实公钥，非诱饵）
const DER_HEX = '';

const pubkey = crypto.createPublicKey({
  key: Buffer.from(DER_HEX, 'hex'),
  format: 'der',
  type: 'spki',
});

// 明文 = '/api/question/27' + now(13位毫秒) + '27' + page
function makePlaintext(now, page) {
  return `/api/question/27${now}27${page}`;
}

function makeToken(now, page) {
  const plaintext = makePlaintext(now, page);
  const enc = crypto.publicEncrypt(
    { key: pubkey, padding: crypto.constants.RSA_PKCS1_PADDING },
    Buffer.from(plaintext, 'utf8')
  );
  return enc.toString('base64');
}

const SESSIONID = process.env.SESSIONID || 'e6opudrz7p7xwhtdmrfbjjram0uawija';
const BASE = 'https://match.yuanrenxue.cn';

async function getTime() {
  const r = await fetch(`${BASE}/api/getTime`, {
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:153.0) Gecko/20100101 Firefox/153.0',
      'X-Requested-With': 'XMLHttpRequest',
      Referer: `${BASE}/match/27`,
      Cookie: `sessionid=${SESSIONID}`,
    },
  });
  const t = await r.text();
  return t.trim();
}

async function getQuestion(page) {
  const now = await getTime();
  const token = makeToken(now, page);
  const url = `${BASE}/api/question/27?page=${page}&pageSize=10&kw=&token=${encodeURIComponent(token)}&now=${now}`;
  const r = await fetch(url, {
    headers: {
      'User-Agent': 'yuanrenxue',
      Accept: 'application/json, text/javascript, */*; q=0.01',
      'X-Requested-With': 'XMLHttpRequest',
      Referer: `${BASE}/match/27`,
      Cookie: `sessionid=${SESSIONID}`,
    },
  });
  return { status: r.status, body: await r.text() };
}

(async () => {
  for (const page of [1, 2, 3, 4, 5]) {
    const { status, body } = await getQuestion(page);
    console.log(`page=${page} status=${status} body=${body}`);
  }
})();
